'use strict';
const{chromium}=require('playwright');const B='https://plan-ex.ru/erpv2/';const ok=(v,m)=>{if(!v)throw Error(m)};
(async()=>{const cs=JSON.parse(Buffer.from(process.env.P12_CREDENTIALS_B64||'','base64').toString('utf8'));const c=cs.find(x=>String(x.role).toUpperCase()==='OWNER');ok(c,'OWNER credentials');const b=await chromium.launch({headless:true});const x=await b.newContext({viewport:{width:1920,height:1080},locale:'ru-RU',timezoneId:'Europe/Moscow'});const p=await x.newPage();try{await p.goto(B+'login');await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(c.username);await p.locator('input[type="password"]').fill(c.password);await p.locator('button[type="submit"],input[type="submit"]').first().click();await p.waitForTimeout(700);ok(!p.url().includes('/login'),'login');let r=await p.goto(B+'company/finance/bank-accounts',{waitUntil:'domcontentloaded'});ok(r.status()===200,'bank HTTP');ok(await p.locator('#bank-classification-register').count()===0,'duplicate classification register removed');ok(await p.locator('#bank-classify-modal').count()===0,'separate classify modal removed');const table=p.locator('table.bank-transactions-table');ok(await table.count()===1,'single bank transactions table');const hs=table.locator('th');const h=(await hs.allTextContents()).map(s=>s.trim());for(const s of ['Дата','Счёт','Контрагент','ИНН','Назначение','Дебет','Кредит','ЦФУ','Статья ДДС','Статус'])ok(h.includes(s),'bank header '+s);ok(!h.includes('Разнести'),'no classify column');const debitIndex=h.indexOf('Дебет');const creditIndex=h.indexOf('Кредит');ok(debitIndex>=0&&creditIndex>=0,'money columns');ok((await hs.nth(debitIndex).evaluate(el=>getComputedStyle(el).textAlign))==='right','debit header right');ok((await hs.nth(creditIndex).evaluate(el=>getComputedStyle(el).textAlign))==='right','credit header right');for(const n of ['date_from','date_to','q','classification_status'])ok(await p.locator(`form.bank-controls-filter [name="${n}"]`).count(),'filter '+n);const banner=p.locator('[data-reconciliation-banner]');await banner.waitFor({state:'visible',timeout:10000});const bannerText=await banner.innerText();ok(bannerText.includes('24.07.2026'),'control date visible');ok(bannerText.includes('расхождений нет'),'current reconciliation clean');const rows=table.locator('tbody tr[data-tx-id]');ok(await rows.count()>0,'bank rows');const row=rows.first();const cells=row.locator('td');ok((await cells.nth(debitIndex).evaluate(el=>getComputedStyle(el).textAlign))==='right','debit cell right');ok((await cells.nth(creditIndex).evaluate(el=>getComputedStyle(el).textAlign))==='right','credit cell right');await row.click();await p.waitForTimeout(250);ok(!await p.locator('#tx-detail-modal').evaluate(el=>el.classList.contains('is-open')),'single click must not open details');await row.dblclick();await p.locator('#tx-detail-modal.is-open').waitFor({state:'visible',timeout:10000});const detail=p.locator('#tx-detail-modal');await detail.locator('[data-tx-detail-classification]').waitFor({state:'visible',timeout:10000});await p.waitForTimeout(500);const detailText=await detail.innerText();ok(detailText.includes('Разнесение операции')||detailText.includes('внутренний перевод'),'classification inside details');if(detailText.includes('Разнесение операции')){ok(await detail.locator('[name="cash_flow_center_id"]').count(),'CFU in details');ok(await detail.locator('[name="dds_category_id"]').count(),'DDS in details');ok(await detail.getByText('Сохранить разнесение',{exact:true}).count(),'save classification in details');}const recon=await p.request.get(B+'company/finance/bank-accounts/reconciliation/json');ok(recon.status()===200,'recon HTTP');const j=await recon.json();ok(j.status==='ok','reconciliation service '+(j.message||''));ok(j.reconciliation.control_from_date==='2026-07-24','reconciliation cutoff');ok(j.reconciliation.summary.all_ok===true,'reconciliation clean after cutoff');console.log('P41_RECON_SUMMARY='+JSON.stringify(j.reconciliation.summary||{}));await p.locator('#tx-detail-modal .modal-close').click();r=await p.goto(B+'company/finance/settings/matching-rules',{waitUntil:'domcontentloaded'});ok(r.status()===200,'rules HTTP');await p.getByText('Справочник ЦФУ',{exact:true}).first().waitFor({state:'visible',timeout:10000});await p.locator('#matching-rule-create-btn').click();await p.waitForTimeout(500);const m=p.locator('#matching-rule-create-modal.is-open');await m.waitFor({state:'attached',timeout:10000});for(const n of ['target_cash_flow_center_id','target_dds_category_id','target_cash_account_id','priority'])ok(await m.locator(`[name="${n}"]`).count(),'field '+n);ok(await m.locator('option[value="transfer_to_cash"]').count(),'bank-to-cash');ok(!/(Fatal error|Parse error|Uncaught TypeError)/i.test(await p.locator('body').innerText()),'fatal');console.log('P41_FINANCE_RUNTIME_OK');}finally{await b.close();}})().catch(e=>{console.error(e);process.exit(1)});
